'use strict';
const $=id=>document.getElementById(id), money=new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const fmt=n=>money.format(n), percent=n=>n.toFixed(1)+'%', esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let positions=[],equity=10000000,source='No portfolio loaded';
const scenarios=[{name:'Market −5%',kind:'all',shock:-.05},{name:'Technology −8%',kind:'Technology',shock:-.08},{name:'Bond price −2.5%',kind:'Fixed Income',shock:-.025},{name:'Energy −10%',kind:'Energy',shock:-.10}];
const impact=s=>Risk.stress(positions,s.kind,s.shock).reduce((sum,o)=>sum+o.x,0), order=o=>Object.entries(o).sort((a,b)=>b[1]-a[1]);
const largest=()=>[...positions].sort((a,b)=>Math.abs(Risk.value(b))-Math.abs(Risk.value(a)))[0];
const pf=()=>Risk.summary(positions,equity), sectors=()=>order(Risk.totals(positions,'sector')), cps=()=>order(Risk.totals(positions,'cp'));
function feedback(text,error=false){$('feedback').textContent=text;$('feedback').classList.toggle('error',error);$('feedback').hidden=false;}
function alerts(){
  const out=[],p=pf(),add=(level,title,text)=>out.push({level,title,text});
  if(!positions.length)return out;
  const old=positions.filter(p=>p.asOf&&(Date.now()-Date.parse(p.asOf))/86400000>7);if(old.length)add('warning','Stale position prices',`${old.length} positions have observations more than seven calendar days old.`);
  const undated=positions.filter(p=>!p.asOf);if(undated.length)add('warning','Price observation dates missing',`${undated.length} positions have no price date. Imported values are unverified inputs.`);
  if(p.gross>120)add('danger','Gross exposure exceeds limit',`${percent(p.gross)} of equity versus the 120% limit.`);
  for(const [sector,value] of sectors())if(value/equity>.35)add('danger',`${sector} concentration breached`,`${percent(value/equity*100)} of equity versus the 35% sector limit.`);
  for(const pos of positions)if(Math.abs(Risk.value(pos))/equity>.15)add('danger',`${pos.ticker} concentration breached`,`${percent(Math.abs(Risk.value(pos))/equity*100)} of equity versus the 15% position limit.`);
  for(const [cp,value] of cps())if(value/equity>.25)add('warning',`${cp} exposure elevated`,`${percent(value/equity*100)} of equity versus the 25% counterparty limit. This is gross custody exposure, not estimated default loss.`);
  for(const s of scenarios)if(impact(s)<-equity*.05)add('warning',`${s.name} exceeds stress budget`,`${fmt(-impact(s))} modeled loss versus the 5% equity budget (${fmt(equity*.05)}).`);
  const slow=positions.filter(p=>Risk.exitDays(p)>1),unknown=positions.filter(p=>Risk.exitDays(p)===null);
  if(slow.length)add('warning','Exit time exceeds one day',slow.map(p=>`${p.ticker}: ${Risk.exitDays(p).toFixed(2)} days`).join('; ')+', at 10% of normal ADV.');
  if(unknown.length)add('warning','Liquidity data missing',`${unknown.length} positions have no average daily volume; exit time cannot be estimated.`);
  if(positions.some(p=>p.cp==='Unspecified'))add('warning','Counterparty data incomplete','Unspecified positions are grouped together. Supply counterparties for meaningful custody concentration.');
  return out;
}
function alertHTML(a){return `<div class="alert ${a.level}"><div class="alert-icon" aria-hidden="true">${a.level==='danger'?'!':'△'}</div><div><h3>${esc(a.title)}</h3><p>${esc(a.text)}</p></div></div>`;}
function renderAlerts(){const all=alerts(),selected=$('severityFilter').value;$('alertPreview').innerHTML=all.slice(0,2).map(alertHTML).join('')||'<div class="empty">No current breaches</div>';$('allAlerts').innerHTML=all.filter(a=>selected==='all'||a.level===selected).map(alertHTML).join('')||'<div class="empty">No alerts at this severity</div>';}
function renderPositions(){
  const q=$('positionSearch').value.toLowerCase(),sector=$('sectorFilter').value,sort=$('positionSort').value;
  const rows=positions.filter(p=>(sector==='all'||p.sector===sector)&&`${p.ticker} ${p.name} ${p.cp}`.toLowerCase().includes(q));
  rows.sort((a,b)=>sort==='ticker'?a.ticker.localeCompare(b.ticker):sort==='liquidity'?(Risk.exitDays(b)??Infinity)-(Risk.exitDays(a)??Infinity):sort==='pnl'?Risk.summary([a],equity).day-Risk.summary([b],equity).day:Math.abs(Risk.value(b))-Math.abs(Risk.value(a)));
  $('positionCount').textContent=`${rows.length} of ${positions.length} positions`;
  $('positionRows').innerHTML=rows.map(p=>{const w=Math.abs(Risk.value(p))/equity*100,day=Risk.summary([p],equity).day,days=Risk.exitDays(p);return `<tr><td><div class="ticker">${esc(p.ticker)} <span class="pill">${p.side<0?'Short':'Long'}</span></div><div class="sub">${esc(p.name)} · ${esc(p.sector)}</div></td><td>${fmt(Risk.value(p))}</td><td>${percent(w)}</td><td class="${day<0?'down':'up'}">${fmt(day)}</td><td>${p.beta.toFixed(2)}</td><td>${days===null?'Unknown':days<.01?'&lt;0.01':days.toFixed(2)}</td><td>${esc(p.cp)}<div class="sub">${esc(p.credit)} · supplied label</div></td><td><span class="pill ${w>15?'down':''}">${w>15?'High':w>10?'Watch':'Normal'}</span></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No positions match these filters.</td></tr>';
}
function renderPosture(){
  const p=pf(),cp=cps()[0],days=positions.map(Risk.exitDays),missing=days.filter(x=>x===null).length,maxDays=Math.max(0,...days.filter(x=>x!==null));
  const items=[['Gross exposure',p.gross/120*100,`${percent(p.gross)} of equity / 120% limit`],['Liquidity',maxDays*100,`${maxDays.toFixed(2)} days maximum / 1 day limit${missing?`; ${missing} unknown`:''}`],['Largest position',p.largest/15*100,`${percent(p.largest)} of equity / 15% limit`],['Counterparty',cp[1]/equity/.25*100,`${esc(cp[0])}: ${percent(cp[1]/equity*100)} of equity / 25% limit`]];
  $('riskPosture').innerHTML=items.map(([name,use,note])=>`<div class="risk-row"><div class="risk-title"><span>${name}</span><b class="${use>100?'down':''}">${Math.round(use)}% of limit</b></div><div class="meter"><span style="width:${Math.min(100,use)}%;background:var(--${use>100?'red':'green'})"></span></div><small>${note}</small></div>`).join('');
}
function renderExplanation(){
  const top=sectors()[0],pos=largest(),colors=['#64e3bd','#78adff','#ae9aff','#ffbd69','#ff898c','#8ccbd1'];
  const total=sectors().reduce((s,o)=>s+o[1],0);
  $('explanation').innerHTML=`<p style="font-size:19px;line-height:1.5;margin:0 0 12px"><b>${esc(top[0])} is your largest sector exposure.</b></p><p class="notice">${percent(top[1]/equity*100)} of equity is allocated on a gross basis. ${esc(pos.ticker)} is the largest position at ${percent(Math.abs(Risk.value(pos))/equity*100)} of equity.</p><div class="allocation" aria-hidden="true">${sectors().map(([n,v],i)=>`<span style="width:${v/total*100}%;background:${colors[i%colors.length]}"></span>`).join('')}</div><div class="allocation-key">${sectors().map(([n,v],i)=>`<div><span><i style="background:${colors[i%colors.length]}"></i>${esc(n)}</span><b>${percent(v/equity*100)} of equity</b></div>`).join('')}</div><p class="notice">Bar shows share of gross market value; labels use portfolio equity. Short positions count toward gross concentration.</p>`;
}
function renderStress(){
  if(!positions.length){$('customLoss').textContent='—';$('stressBreakdown').textContent='Import positions to run stress.';return;}
  const raw=$('shockMove').value,move=Number(raw),target=$('shockTarget').value;
  if(raw===''||!Number.isFinite(move)||move< -100||move>100){feedback('Enter a shock between −100% and +100%.',true);return;}
  const result=Risk.stress(positions,target,move/100),total=result.reduce((s,o)=>s+o.x,0),max=Math.max(1,...result.map(o=>Math.abs(o.x)));
  $('customLoss').textContent=`${fmt(total)} (${percent(total/equity*100)})`;$('customLoss').className=total<0?'down':'up';
  $('stressBreakdown').innerHTML=result.filter(o=>o.x!==0).sort((a,b)=>Math.abs(b.x)-Math.abs(a.x)).map(o=>`<div class="breakdown-row"><span>${esc(o.p.ticker)}</span><div class="breakdown-track"><span style="width:${Math.abs(o.x)/max*100}%;background:var(--${o.x<0?'red':'green'})"></span></div><b class="${o.x<0?'down':'up'}">${fmt(o.x)}</b></div>`).join('')||'<p class="notice">No modeled impact for this selection.</p>';
}
function renderSurvival(){
  const worst=Math.min(0,...scenarios.map(impact)),loss=-worst,remaining=equity-loss;
  $('survival').innerHTML=`<p>Largest modeled loss: <b class="down">${fmt(loss)}</b></p><p class="notice">Across the four predefined scenarios, equity remaining is <b>${fmt(remaining)}</b>.</p><div class="risk-row"><div class="risk-title"><span>Loss / equity</span><b>${percent(loss/equity*100)}</b></div><div class="meter"><span style="width:${Math.min(100,loss/equity*100)}%;background:var(--red)"></span></div></div><p class="notice">${remaining>0?`Recovering this loss requires a ${percent(loss/remaining*100)} gain on the remaining equity.`:'Modeled loss exhausts equity; a recovery percentage is not meaningful.'}</p><p class="notice">These scenarios are illustrative, not a maximum-loss bound. Liquidity, financing costs, nonlinear payoffs and changing correlations are excluded.</p>`;
}
function refreshSelectors(){for(const id of ['sectorFilter','shockTarget']){const select=$(id),old=select.value;select.replaceChildren(new Option(id==='sectorFilter'?'All sectors':'Whole portfolio','all'),...sectors().map(([s])=>new Option(s,s)));select.value=[...select.options].some(o=>o.value===old)?old:'all';}}
function render(){
  $('portfolioEmpty').innerHTML=positions.length?'':'<div class="portfolio-empty"><h2>Load a portfolio to begin</h2><p>Import your positions, set portfolio equity, and review source dates. Government monitoring uses official public data independently.</p><p class="notice">No demonstration holdings are loaded automatically. Licensed connections are configured under Data connections.</p></div>';
  document.querySelectorAll('#overview > .grid-2').forEach(x=>x.hidden=!positions.length);
  if(!positions.length){$('metrics').innerHTML='';$('sourceLabel').textContent=source;renderPositions();renderAlerts();renderStress();$('scenarioCards').innerHTML='';$('survival').textContent='Import positions to calculate scenario losses.';return;}

  const p=pf();$('sourceLabel').textContent=source;
  $('metrics').innerHTML=[['Portfolio equity',fmt(equity),'User-supplied capital',''],["Day P&L",fmt(p.day),'From supplied price changes',p.day<0?'down':'up'],['Gross exposure',percent(p.gross),'Limit 120%',p.gross>120?'down':''],['Net exposure',percent(p.net),'Signed value / equity',''],['Largest position',percent(p.largest),'Limit 15%',p.largest>15?'down':'']].map(x=>`<article class="card metric"><label>${x[0]}</label><strong class="${x[3]}">${x[1]}</strong><small>${x[2]}</small></article>`).join('');
  const max=Math.max(1,...scenarios.map(s=>Math.abs(impact(s))));$('scenarioChart').innerHTML=scenarios.map(s=>{const x=impact(s);return `<div><div class="impact-label"><span>${s.name}</span><b class="${x<0?'down':'up'}">${fmt(x)}</b></div><div class="impact-track"><span class="${x>=0?'gain':''}" style="width:${Math.abs(x)/max*100}%"></span></div></div>`}).join('');
  $('scenarioCards').innerHTML=scenarios.map(s=>{const x=impact(s);return `<article class="scenario"><h3>${s.name}</h3><strong class="${x<0?'down':'up'}">${fmt(x)}</strong><p>${percent(x/equity*100)} of equity</p></article>`}).join('');
  refreshSelectors();renderPositions();renderPosture();renderExplanation();renderAlerts();renderStress();renderSurvival();
}
function show(id){const names={workspace:'Portfolio workspace',systemic:'Systemic risk controls',government:'Government monitor',exchanges:'Global market directory',connections:'Data connections',evidence:'Decision evidence',overview:'Executive dashboard',positions:'Position risk',stress:'Stress laboratory',alerts:'Risk alerts',ask:'Ask Risk',method:'Methodology'};if(!names[id])return;document.querySelector('.portfolio-bar').hidden=['workspace','systemic','government','exchanges','connections','evidence','method'].includes(id);document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav button').forEach(x=>{x.classList.toggle('active',x.dataset.view===id);if(x.dataset.view===id)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')});$('pageTitle').textContent=names[id];window.scrollTo({top:0,behavior:'instant'});}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function answer(q){
  if(!positions.length)return 'Import a portfolio first. The government monitor has separate official-source observations.';
  const low=q.toLowerCase(),p=pf(),pos=largest(),top=sectors()[0];
  if(/chang|increas|yesterday|histor/.test(low))return 'This workspace contains one snapshot. It cannot establish what changed over time. Import a current portfolio to inspect its exposures.';
  if(/liquid|exit|volume/.test(low)){const known=positions.filter(p=>Risk.exitDays(p)!==null).sort((a,b)=>Risk.exitDays(b)-Risk.exitDays(a)),missing=positions.length-known.length;return `${known.length?`${known[0].ticker} has the longest estimated exit time: ${Risk.exitDays(known[0]).toFixed(3)} trading days at 10% of supplied ADV.`:'No positions have supplied ADV.'} ${missing} positions have unknown exit time. Normal-volume estimates can deteriorate in stressed markets.`;}
  if(/counter|broker|custod/.test(low)){const cp=cps()[0];return `${cp[0]} is the largest custody grouping at ${percent(cp[1]/equity*100)} of equity. Gross exposure is compared with a 25% illustrative limit. Supplied credit labels are unverified; no counterparty default-loss estimate is available.`;}
  if(/shock|fall|stress|market/.test(low))return `A −5% whole-portfolio market move, scaled by each position's beta, produces ${fmt(impact(scenarios[0]))}. The direct −8% technology shock produces ${fmt(impact(scenarios[1]))}. Use Stress lab to choose an exact move and sector.`;
  if(/largest|concentr|sector/.test(low))return `${pos.ticker} is the largest position at ${percent(Math.abs(Risk.value(pos))/equity*100)} of equity. ${top[0]} is the largest sector at ${percent(top[1]/equity*100)} on a gross basis.`;
  return `Gross exposure is ${percent(p.gross)}, net exposure is ${percent(p.net)}, and calculated day P&L is ${fmt(p.day)}. ${alerts().length} alerts are active. I can summarize concentration, liquidity, counterparties and predefined stress scenarios; I cannot answer arbitrary research questions.`;
}
function ask(q){for(const [kind,text] of [['user',q],['system',answer(q)]]){const el=document.createElement('div');el.className='bubble '+kind;el.textContent=text;$('conversation').append(el)}$('askInput').value='';$('conversation').lastElementChild.scrollIntoView({block:'nearest'});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>show(b.dataset.goto));document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>ask(b.dataset.question));
$('positionSearch').oninput=renderPositions;$('sectorFilter').onchange=renderPositions;$('positionSort').onchange=renderPositions;$('severityFilter').onchange=renderAlerts;$('runStress').onclick=renderStress;
$('applyEquity').onclick=()=>{const n=Number($('equityInput').value);if(!Number.isFinite(n)||n<=0){feedback('Portfolio equity must be a positive number.',true);return}equity=n;render();feedback('Equity updated. Exposure ratios and alerts recalculated.');};
$('importBtn').onclick=()=>$('csvFile').click();
$('csvFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('Use a CSV smaller than 2 MB.');const next=Risk.parseCSV(await file.text());positions=next;source='Imported · verify source dates';$('positionSearch').value='';$('conversation').replaceChildren();$('dataNote').textContent='Imported positions are unsaved. Use Portfolio workspace to save them on this computer. Confirm equity matches this snapshot.';render();feedback(`Imported ${next.length} positions. Check portfolio equity before interpreting risk ratios.`);document.dispatchEvent(new CustomEvent('portfolio-imported',{detail:{count:next.length}}));}catch(error){feedback(error.message+' The previous portfolio is unchanged.',true);}finally{e.target.value=''}};
$('resetBtn').onclick=()=>{positions=structuredClone(samplePositions);equity=10000000;source='Demonstration · synthetic holdings';$('equityInput').value=equity;$('positionSearch').value='';$('conversation').replaceChildren();$('dataNote').textContent='Illustrative positions, not live prices. Imports stay in this tab and reset on reload.';render();feedback('Sample portfolio restored.');};
$('templateBtn').onclick=()=>download('riskpulse-template.csv','ticker,name,shares,price,sector,day,beta,adv,counterparty,credit,side,currency,fx_to_usd,asof,instrument_id,mic,source\nDEMO,Example Holding,100,50,Technology,0,1,100000,Example Broker,N/A,long,USD,1,,,,Demonstration\n','text/csv');
$('downloadBtn').onclick=()=>{const p=pf();download('riskpulse-report.txt',`RISKPulse Portfolio Report\nGenerated: ${new Date().toISOString()}\nSource: ${source}\nPositions: ${positions.length}\n\nEquity: ${fmt(equity)}\nGross exposure: ${percent(p.gross)}\nNet exposure: ${percent(p.net)}\nDay P&L: ${fmt(p.day)}\n\nSCENARIOS\n${scenarios.map(s=>s.name+': '+fmt(impact(s))).join('\n')}\n\nALERTS\n${alerts().map(a=>a.title+': '+a.text).join('\n')||'No current breaches'}\n\nMethod: current signed market values; whole-portfolio shocks scale by supplied beta; sector shocks apply directly. Supplied equity is the denominator. Credit labels are unverified. No live prices or historical comparison. Educational model; not investment advice.`);feedback('Portfolio report downloaded.');};
$('askForm').onsubmit=e=>{e.preventDefault();const q=$('askInput').value.trim();if(q)ask(q)};
if(document.modelContext?.registerTool){try{
 document.modelContext.registerTool({name:'read_portfolio_risk',description:'Read calculated exposures and alerts from this portfolio snapshot.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>({equity,...pf(),alerts:alerts()})});
 document.modelContext.registerTool({name:'run_portfolio_stress',description:'Apply an exact shock between -100 and +100 percent to all positions or an existing sector.',inputSchema:{type:'object',properties:{target:{type:'string'},move_pct:{type:'number',minimum:-100,maximum:100}},required:['target','move_pct'],additionalProperties:false},execute:async input=>{if(!input||!['all',...sectors().map(s=>s[0])].includes(input.target)||!Number.isFinite(input.move_pct)||Math.abs(input.move_pct)>100)throw Error('Invalid target or move');$('shockTarget').value=input.target;$('shockMove').value=input.move_pct;renderStress();show('stress');return{target:input.target,move_pct:input.move_pct,estimated_impact:Risk.stress(positions,input.target,input.move_pct/100).reduce((s,o)=>s+o.x,0)}}});
}catch{}}
render();show('government');
